use hawdb::{Database, Value};
use std::alloc::{GlobalAlloc, Layout, System};
use std::hint::black_box;
use std::sync::atomic::{AtomicBool, AtomicU64, AtomicUsize, Ordering};
use std::sync::Mutex;
use std::time::Instant;

static TRACE: AtomicBool = AtomicBool::new(false);
static SAMPLES: Mutex<[[usize; 32]; 4096]> = Mutex::new([[0; 32]; 4096]);
static SAMPLE_COUNT: AtomicUsize = AtomicUsize::new(0);
unsafe extern "C" { fn backtrace(buffer: *mut *mut std::ffi::c_void, size: i32) -> i32; }
fn sample(calls: u64) {
    if calls % 8192 != 0 || !TRACE.swap(false, Ordering::Relaxed) { return; }
    let index = SAMPLE_COUNT.fetch_add(1, Ordering::Relaxed);
    if index < 4096 {
        let mut frames = [0usize; 32];
        unsafe { backtrace(frames.as_mut_ptr().cast(), 32); }
        SAMPLES.lock().unwrap()[index] = frames;
    }
    TRACE.store(true, Ordering::Relaxed);
}
struct CountingAllocator;
static CALLS: AtomicU64 = AtomicU64::new(0);
static BYTES: AtomicU64 = AtomicU64::new(0);
unsafe impl GlobalAlloc for CountingAllocator {
    unsafe fn alloc(&self, layout: Layout) -> *mut u8 {
        sample(CALLS.fetch_add(1, Ordering::Relaxed));
        BYTES.fetch_add(layout.size() as u64, Ordering::Relaxed);
        unsafe { System.alloc(layout) }
    }
    unsafe fn dealloc(&self, pointer: *mut u8, layout: Layout) {
        unsafe { System.dealloc(pointer, layout) }
    }
    unsafe fn realloc(&self, pointer: *mut u8, layout: Layout, size: usize) -> *mut u8 {
        sample(CALLS.fetch_add(1, Ordering::Relaxed));
        BYTES.fetch_add(size as u64, Ordering::Relaxed);
        unsafe { System.realloc(pointer, layout, size) }
    }
}
